+        implements BatchPhysicalRel {
+
+    public BatchPhysicalVectorSearchTableFunction(
+            RelOptCluster cluster,
+            RelTraitSet traits,
+            RelNode input,
+            RelOptTable searchTable,
+            @Nullable RexProgram projectionOnVectorTable,
+            VectorSearchSpec vectorSearchSpec,
